// Generated by scripts/examples.mjs (npm run examples) from the example files: don't edit.
export default {
  "components": "import { html, define, signal, provide, inject } from 'pith';\n\n// define() makes a custom element: props come from attributes (as signals), slots from its children,\n// and provide/inject passes a value to every component inside, without threading props.\ndefine('rating-stars', (props) => {\n  const max = () => Number(props.max.value) || 5;\n  const value = signal(Number(props.value.value) || 0);\n  const accent = inject('accent', 'currentColor');\n  return html`\n    <span class=\"stars\" role=\"group\" aria-label=${() => `Rating: ${value.value} of ${max()}`}>\n      ${() => Array.from({ length: max() }, (_, i) => html`\n        <button type=\"button\" class=\"star\" style=${`color: ${accent}`} aria-label=${`${i + 1} stars`}\n                aria-pressed=${() => String(i < value.value)} @click=${() => (value.value = i + 1)}>\n          ${() => (i < value.value ? '★' : '☆')}\n        </button>`)}\n    </span>\n  `;\n}, { props: ['max', 'value'] });\n\ndefine('review-card', (props, ctx) => {\n  provide('accent', '#b7791f'); // gold; stars are large text, so 3:1 contrast is enough\n  return html`\n    <article class=\"card\">\n      <h3>${ctx.slot('title')}</h3>\n      ${ctx.slot()}\n      <rating-stars max=\"5\" value=${props.stars}></rating-stars>\n    </article>\n  `;\n}, { props: ['stars'] });\n\nexport default function ComponentsExample() {\n  return html`\n    <review-card stars=\"4\">\n      <span slot=\"title\">A tiny framework</span>\n      <p>Click a star to change the rating.</p>\n    </review-card>\n  `;\n}\n",
  "dialogs": "import { html, signal } from 'pith';\nimport { confirm, dialog, toast } from '../ui.js';\n\n// App code, not framework: app/ui.js builds these on the browser's own <dialog> and popover.\n// They're promises, so the code reads top to bottom.\nexport default function DialogsExample() {\n  const choice = signal('nothing yet');\n\n  const ask = async () => {\n    if (await confirm('Delete the sample file?', { ok: 'Delete', danger: true })) toast('Deleted', { type: 'success' });\n    else toast('Kept it');\n  };\n  const pick = async () => {\n    const color = await dialog((close) => html`\n      <h2>Pick a color</h2>\n      <div class=\"row\">\n        ${['Red', 'Green', 'Blue'].map((c) => html`<button class=\"btn\" type=\"button\" @click=${() => close(c)}>${c}</button>`)}\n      </div>`);\n    choice.value = String(color ?? 'cancelled');\n  };\n\n  return html`\n    <div class=\"row\">\n      <button class=\"btn\" type=\"button\" @click=${ask}>Confirm…</button>\n      <button class=\"btn\" type=\"button\" @click=${pick}>Custom dialog…</button>\n      <button class=\"btn\" type=\"button\" @click=${() => toast('Hello from a toast')}>Toast</button>\n    </div>\n    <p>Picked: <strong>${choice}</strong></p>\n  `;\n}\n",
  "errors": "import { html, define, signal } from 'pith';\n\n// A component that throws (in setup, a ${} hole, or a @click handler) shows its fallback instead,\n// and the rest of the page keeps working. \"Try again\" runs its setup again, from scratch.\ndefine('flaky-panel', () => {\n  const broken = signal(false);\n  const status = () => {\n    if (broken.value) throw new Error('Something broke inside this panel.');\n    return 'Working fine.';\n  };\n  return html`\n    <p>${status}</p>\n    <button class=\"btn\" type=\"button\" @click=${() => (broken.value = true)}>Break it</button>\n  `;\n}, {\n  fallback: (err, retry) => html`\n    <div class=\"card widget-crashed\" role=\"alert\">\n      <p>Crashed: ${err.message}</p>\n      <button class=\"btn primary\" type=\"button\" @click=${retry}>Try again</button>\n    </div>\n  `,\n});\n\nexport default function ErrorsExample() {\n  return html`\n    <flaky-panel></flaky-panel>\n    <p class=\"muted\">This text is outside the panel, so it stays when the panel crashes.</p>\n  `;\n}\n",
  "forms": "import { html, signal, form, rules, fetchJSON } from 'pith';\n\n// form() handles values, validation, accessible errors, submitting and the server's own errors.\n// Try: submit empty, then an address ending in @blocked.test (the server rejects it, shown under Email).\nexport default function FormsExample() {\n  const sent = signal('');\n  const f = form({\n    initial: { name: '', email: '', message: '' },\n    validate: {\n      name: rules.required(),\n      email: [rules.required(), rules.email()],\n      message: [rules.required(), rules.minLength(10)],\n    },\n    onSubmit: async (values) => {\n      await fetchJSON('/api/contact', { json: values });\n      sent.value = `Thanks, ${values.name}!`;\n      f.reset();\n    },\n  });\n\n  return html`\n    <form class=\"form\" novalidate @submit=${f.submit}>\n      ${f.input('name', { label: 'Name', autocomplete: 'name' })}\n      ${f.input('email', { label: 'Email', type: 'email', autocomplete: 'email' })}\n      ${f.textarea('message', { label: 'Message', hint: () => `${f.fields.message.value.length} characters (10 or more)` })}\n      ${() => (f.submitError.value ? html`<p class=\"form-error\" role=\"alert\">${f.submitError.value.message}</p>` : null)}\n      <button class=\"btn primary\" type=\"submit\" ?disabled=${f.submitting}>Send</button>\n      <p class=\"muted\" aria-live=\"polite\">${sent}</p>\n    </form>\n  `;\n}\n",
  "lists": "import { html, signal, repeat, transition } from 'pith';\n\n// repeat() keeps each item's DOM by key and moves it instead of rebuilding it.\n// transition() animates the change: removed items fade out, moved ones slide.\nexport default function ListsExample() {\n  let nextId = 4;\n  const items = signal([\n    { id: 1, name: 'Apples' },\n    { id: 2, name: 'Bread' },\n    { id: 3, name: 'Coffee' },\n  ]);\n  const draft = signal('');\n\n  const add = (e) => {\n    e.preventDefault();\n    const name = draft.value.trim();\n    if (!name) return;\n    transition(() => (items.value = [...items.value, { id: nextId++, name }]));\n    draft.value = '';\n  };\n  const remove = (id) => transition(() => (items.value = items.value.filter((i) => i.id !== id)));\n  const shuffle = () => transition(() => (items.value = [...items.value].sort(() => Math.random() - 0.5)));\n\n  return html`\n    <form class=\"row\" @submit=${add}>\n      <label class=\"sr-only\" for=\"list-new\">New item</label>\n      <input id=\"list-new\" class=\"input\" placeholder=\"New item\" .value=${draft}\n             @input=${(e) => (draft.value = e.target.value)}>\n      <button class=\"btn primary\">Add</button>\n      <button class=\"btn\" type=\"button\" @click=${shuffle}>Shuffle</button>\n    </form>\n    <ul class=\"example-list motion\">\n      ${repeat(items, (i) => i.id, (i) => html`\n        <li class=\"example-item\">\n          <span>${i.name}</span>\n          <button class=\"icon-btn danger\" type=\"button\" aria-label=${`Remove ${i.name}`} @click=${() => remove(i.id)}>×</button>\n        </li>\n      `)}\n    </ul>\n  `;\n}\n",
  "paginated": "import { html, paginated, repeat, fetchJSON } from 'pith';\n\n// paginated() loads a list a page at a time. The fetcher gets the page number and returns\n// { items, next }; \"Load more\" appends the next page, and hasMore turns false on the last one.\nexport default function PaginatedExample() {\n  const team = paginated(({ page, signal }) => fetchJSON(`/api/team?page=${page}`, { signal }));\n\n  return html`\n    ${team.render((people) => html`\n      <ol class=\"example-list\">\n        ${repeat(people, (p) => p.id, (p) => html`<li class=\"example-item\">${p.name}</li>`)}\n      </ol>`)}\n    <div class=\"load-more\">\n      ${() => (team.hasMore.value\n        ? html`<button class=\"btn\" type=\"button\" ?disabled=${team.loadingMore} @click=${team.loadMore}>\n            ${() => (team.loadingMore.value ? 'Loading…' : 'Load more')}</button>`\n        : html`<p class=\"muted\">That's everyone.</p>`)}\n    </div>\n  `;\n}\n",
  "resource": "import { html, signal, resource, fetchJSON } from 'pith';\n\n// resource() loads data and tracks loading and errors. It re-runs when a signal it read changes (`q`),\n// and cancels the old request first, so a slow answer can never overwrite a newer one.\nexport default function ResourceExample() {\n  const q = signal('');\n  const people = resource(({ signal }) => fetchJSON(`/api/team?q=${encodeURIComponent(q.value)}`, { signal }));\n\n  return html`\n    <div class=\"search-row\">\n      <label class=\"sr-only\" for=\"resource-q\">Search people</label>\n      <input id=\"resource-q\" class=\"input\" type=\"search\" placeholder=\"Search people\" .value=${q}\n             @input=${(e) => (q.value = e.target.value)}>\n      <span class=\"muted small\" aria-live=\"polite\">${() => (people.loading.value ? 'Loading…' : '')}</span>\n      <button class=\"btn\" type=\"button\" @click=${people.refetch}>Reload</button>\n    </div>\n    ${people.render((page) => (page.items.length\n      ? html`<ul class=\"example-list\">${page.items.map((p) => html`<li class=\"example-item\">${p.name} <span class=\"muted\">${p.role}</span></li>`)}</ul>`\n      : html`<p class=\"empty\">No one matches.</p>`))}\n  `;\n}\n",
  "router": "import { html } from 'pith';\nimport { router } from '../router.js';\n\n// The router keeps the path and the ?query in signals. setQuery() changes the URL without a re-render,\n// so a reload or a shared link keeps the choice. Links are plain <a href>.\nexport default function RouterExample() {\n  const tabs = ['one', 'two', 'three'];\n  const tab = () => router.query.value.tab ?? 'one';\n\n  return html`\n    <p>Path: <code>${router.path}</code> · Query: <code>${() => new URLSearchParams(router.query.value).toString() || '(none)'}</code></p>\n    <div class=\"row\" role=\"group\" aria-label=\"Pick a tab\">\n      ${tabs.map((t) => html`\n        <button class=\"chip\" type=\"button\" aria-pressed=${() => String(tab() === t)}\n                @click=${() => router.setQuery({ tab: t })}>Tab ${t}</button>`)}\n    </div>\n    <p>Showing tab <strong>${tab}</strong>. Reload: it stays.</p>\n    <p class=\"row\">\n      <a href=\"/docs/forms\">A :param route (/docs/forms)</a>\n      <a href=\"/settings/account\">A guarded route (needs sign-in)</a>\n    </p>\n  `;\n}\n",
  "selector": "import { html, signal, selector } from 'pith';\n\n// Marking the selected row: with selector(), a click re-runs only the 2 rows whose answer changed.\n// Comparing in every row (selected.value === id) re-runs all of them. The counter shows how many ran.\nexport default function SelectorExample() {\n  const ids = Array.from({ length: 100 }, (_, i) => i + 1);\n  const selected = signal(0);\n  const isSelected = selector(selected);\n  const naive = signal(false);\n  const reran = signal(0);\n  let runs = 0;\n\n  const rowClass = (id) => () => {\n    runs++;\n    const on = naive.value ? selected.value === id : isSelected(id);\n    return on ? 'grid-cell selected' : 'grid-cell';\n  };\n  const pick = (id) => {\n    runs = 0;\n    selected.value = id;\n    reran.value = runs;\n  };\n\n  return html`\n    <div class=\"row\">\n      <label class=\"check-label\"><input type=\"checkbox\" .checked=${naive}\n        @change=${(e) => (naive.value = e.target.checked)}> Compare in every row instead</label>\n      <p class=\"muted\" aria-live=\"polite\">Rows re-run by the last click: <strong>${reran}</strong> of ${ids.length}</p>\n    </div>\n    <div class=\"cell-grid\">\n      ${ids.map((id) => html`<button type=\"button\" class=${rowClass(id)} @click=${() => pick(id)}>${id}</button>`)}\n    </div>\n  `;\n}\n",
  "signals": "import { html, signal, computed } from 'pith';\n\n// A signal holds a value. A computed derives one. Both are just put in the template:\n// a click changes `count`, and only the two numbers on screen update.\nexport default function SignalsExample() {\n  const count = signal(0);\n  const double = computed(() => count.value * 2);\n\n  return html`\n    <p class=\"example-big\">${count} <span class=\"muted\">× 2 = ${double}</span></p>\n    <div class=\"row\">\n      <button class=\"btn\" type=\"button\" @click=${() => count.value--}>−1</button>\n      <button class=\"btn primary\" type=\"button\" @click=${() => count.value++}>+1</button>\n      <button class=\"btn ghost\" type=\"button\" @click=${() => (count.value = 0)}>Reset</button>\n    </div>\n  `;\n}\n",
  "store": "import { html, createStore } from 'pith';\n\n// createStore() turns each key into a signal. With `persist` it's saved to localStorage, restored on\n// reload, and kept in step across tabs: open this page in a second tab and change the note there.\nconst notes = createStore({ note: '', saves: 0 }, { persist: 'pith-features-note' });\n\nexport default function StoreExample() {\n  const save = (e) => {\n    notes.note.value = e.target.value;\n    notes.saves.value++;\n  };\n\n  return html`\n    <label class=\"field-label\" for=\"store-note\">A note that survives reloads</label>\n    <textarea id=\"store-note\" class=\"input\" rows=\"3\" .value=${notes.note} @input=${save}></textarea>\n    <p class=\"muted\">Saved ${notes.saves} times. Reload the page, or open it in another tab.</p>\n  `;\n}\n",
};
